def format_bytes(n):
    """Format bytes into a human-readable size."""
    if n < 0:
        raise ValueError("n must be non-negative")

    if n == 0:
        return "0 B"

    units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB']
    unit_index = 0

    while n >= 1024 and unit_index < len(units) - 1:
        n /= 1024
        unit_index += 1

    return f"{n:.1f} {units[unit_index]}"
